import json,pathlib,datetime,collections,statistics
p=pathlib.Path('tmp/ci-speed'); groups=collections.defaultdict(list)
def dt(s): return datetime.datetime.fromisoformat(s.replace('Z','+00:00'))
for r in json.loads((p/'runs-before.json').read_text()):
 for j in json.loads((p/f"jobs-{r['databaseId']}.json").read_text()).get('jobs',[]):
  if j['conclusion']!='success':continue
  steps=[s for s in j['steps'] if s.get('started_at') and s.get('completed_at')]
  for s in steps:
   d=(dt(s['completed_at'])-dt(s['started_at'])).total_seconds()
   groups[s['name']].append(d)
for k,v in sorted(groups.items(),key=lambda x:statistics.median(x[1]),reverse=True)[:25]: print(round(statistics.median(v)),len(v),k)
