import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";

const read = name => readFileSync(new URL(`../../.github/workflows/${name}.yml`, import.meta.url), "utf8");

for (const name of ["ci", "e2e-backend", "e2e-ui", "sanitizers", "codeql", "gitleaks", "dependency-review", "mutants"]) {
  test(`${name} reports required checks for merge candidates`, () => {
    const workflow = read(name);
    assert.match(workflow, /^  merge_group:\n    types: \[checks_requested\]/m);
    assert.match(workflow, /^  pull_request:/m);
    if (name !== "dependency-review") assert.match(workflow, /^  push:/m);
  });
}

for (const name of ["sanitizers", "codeql", "gitleaks", "dependency-review"]) {
  test(`${name} cancels superseded candidates without canceling publication runs`, () => {
    const workflow = read(name);
    assert.match(workflow, /group: \$\{\{ github.workflow \}\}-\$\{\{ github.event_name \}\}-\$\{\{ github.event.pull_request.number \|\| github.ref \}\}/);
    assert.match(workflow, /cancel-in-progress: \$\{\{ github.event_name == 'pull_request' \|\| github.event_name == 'merge_group' \}\}/);
  });
}

test("dependency review compares merge-group base and head without requiring a PR payload", () => {
  const workflow = read("dependency-review");
  assert.match(workflow, /base-ref: \$\{\{ github.event.merge_group.base_sha \|\| github.event.pull_request.base.sha \}\}/);
  assert.match(workflow, /head-ref: \$\{\{ github.event.merge_group.head_sha \|\| github.event.pull_request.head.sha \}\}/);
  assert.match(workflow, /comment-summary-in-pr: \$\{\{ github.event_name == 'pull_request' && 'on-failure' \|\| 'never' \}\}/);
  assert.doesNotMatch(workflow, /warn-only: true|if:.*pull_request/);
});

// Health inherits the caller's exact source/event/run, avoiding a second coverage producer.
test("Health checks are called by the merge-candidate UI orchestrator", () => {
  assert.match(read("check-health"), /^  workflow_call:$/m);
  assert.match(read("e2e-ui"), /uses: \.\/\.github\/workflows\/check-health\.yml/);
});
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";

test("full health builds frontend before Tauri compilation on a fresh checkout", () => {
  const script = readFileSync(new URL("../check-health.sh", import.meta.url), "utf8");
  assert.ok(script.indexOf("npm run build") < script.indexOf("cargo clippy"), "Tauri generate_context requires actual frontendDist before Clippy/tests");
  assert.equal([...script.matchAll(/npm run build/g)].length, 1, "full health should not build frontend twice");
});

test("health installs source scanners while Gitleaks owns the full-history scan", () => {
  const workflow = readFileSync(new URL("../../.github/workflows/check-health.yml", import.meta.url), "utf8");
  assert.doesNotMatch(workflow, /actions-rs\/toolchain@/);
  assert.match(workflow, /dtolnay\/rust-toolchain@stable/);
  assert.match(workflow, /tool: cargo-deny,cargo-machete,typos-cli,shellcheck/);
  const secrets = readFileSync(new URL("../../.github/workflows/gitleaks.yml", import.meta.url), "utf8");
  assert.match(secrets, /fetch-depth: 0/);
  assert.match(secrets, /GITLEAKS_VERSION: 8\.30\.1/);
  assert.match(workflow, /go install github\.com\/rhysd\/actionlint\/cmd\/actionlint@v1\.7\.12/);
  assert.match(readFileSync(new URL("../check-health.sh", import.meta.url), "utf8"), /for tool in cargo-deny cargo-machete typos gitleaks shellcheck actionlint/);
});

test("Windows health and diagnostic gates explicitly execute Bash", () => {
  for (const [file, name] of [["check-health.yml", "Diagnostic and release gate regressions (all platforms)"]]) {
    const workflow = readFileSync(new URL(`../../.github/workflows/${file}`, import.meta.url), "utf8");
    const step = workflow.split(/^      - /m).find((value) => value.startsWith(`name: ${name}\n`));
    assert.ok(step, name);
    assert.match(step, /^        shell: bash$/m, "PowerShell must not treat .sh as a file association or pass test globs literally");
  }
  assert.match(readFileSync(new URL("../../.github/workflows/check-health.yml", import.meta.url), "utf8"), /defaults:\n      run:\n        shell: bash/);
});

test("health runs for every PR and retains independent platform results", () => {
  const workflow = readFileSync(new URL("../../.github/workflows/check-health.yml", import.meta.url), "utf8");
  assert.match(workflow, /^  workflow_call:$/m);
  const caller = readFileSync(new URL("../../.github/workflows/e2e-ui.yml", import.meta.url), "utf8");
  assert.match(caller, /^  pull_request:$/m);
  assert.match(caller, /uses: \.\/\.github\/workflows\/check-health\.yml/);
  assert.match(workflow, /^concurrency:\n  group: health-.*\n  cancel-in-progress: \$\{\{ github.event_name == 'pull_request' \|\| github.event_name == 'merge_group' \|\| github.event_name == 'push' \}\}$/m);
  assert.match(workflow, /^      fail-fast: false$/m);
});

test("Codecov receives the frontend and Rust coverage produced by CI", () => {
  const workflow = readFileSync(new URL("../../.github/workflows/ci.yml", import.meta.url), "utf8");
  const step = workflow.split(/^      - /m).find((value) => value.startsWith("name: Upload coverage to Codecov\n"));
  assert.ok(step, "the Codecov upload step must exist");
  const health = readFileSync(new URL("../../.github/workflows/check-health.yml", import.meta.url), "utf8");
  assert.match(health, /files: frontend\/coverage\/lcov\.info/, "Health publishes current frontend coverage");
  assert.match(step, /files:.*src-tauri\/lcov\.info/, "Rust coverage must remain part of the upload");
});

test("native workspace test passes collect and upload their own platform coverage", () => {
  const workflow = readFileSync(new URL("../../.github/workflows/ci.yml", import.meta.url), "utf8");
  const steps = workflow.split(/^      - /m);
  const install = steps.find(value => value.startsWith("name: Install cargo-llvm-cov and cargo-nextest\n"));
  const native = steps.find(value => value.startsWith("name: Test + coverage (macOS)\n"));
  const upload = steps.find(value => value.startsWith("name: Upload coverage to Codecov\n"));
  assert.ok(install && native && upload);
  assert.doesNotMatch(install, /if:/, "every native test platform needs the coverage tool");
  assert.match(install, /cargo-llvm-cov@0\.8\.7,cargo-nextest@0\.9\.148/);
  for (const platform of ["macOS", "Linux"]) {
    const pass = steps.find(value => value.startsWith(`name: Test + coverage (${platform})\n`));
    assert.ok(pass);
    assert.match(pass, /cargo llvm-cov nextest --no-report --locked -p mesh-talk --no-tests fail --no-fail-fast --retries 0 --user-config-file none --profile default/);
    assert.match(pass, /cargo llvm-cov --no-report --locked --workspace --exclude mesh-talk/);
