# Scope: ONLY `mesh-talk-core --lib` (the UI-free core). The Tauri app links
# GTK/WebKit C libraries whose internals trip ASan with false positives we can't
# fix from here, so the app is deliberately excluded.
#
# Run on PRs targeting main so branch protection can require this memory-safety
# check before merge. Run again on main so the README badge reflects the merged
# code; keep the weekly run to catch toolchain and dependency drift.
# ASan needs the nightly toolchain + `-Z build-std` (a full std rebuild).
on:
  merge_group:
    types: [checks_requested]
  pull_request:
    branches: [main]
  push:
    branches: [main]
  schedule:
    - cron: "0 6 * * 1" # Mondays 06:00 UTC
  workflow_dispatch:

# Read-only: just checks out and runs the test suite under the sanitizer.
permissions:
  contents: read

env:
  CARGO_TERM_COLOR: always

concurrency:
  group: ${{ github.workflow }}-${{ github.event_name }}-${{ github.event.pull_request.number || github.ref }}-${{ github.event_name == 'push' && github.run_id || 'candidate' }}
  cancel-in-progress: ${{ github.event_name == 'pull_request' || github.event_name == 'merge_group' }}

jobs:
  asan:
    name: ASan + LeakSanitizer (core)
    runs-on: ubuntu-latest
    steps:
      - name: Checkout
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1

      # ASan instrumentation + `-Z build-std` both require nightly; `rust-src` is
      # the std source `-Z build-std` recompiles against the sanitizer runtime.
      - name: Install Rust nightly toolchain
        uses: dtolnay/rust-toolchain@nightly
        with:
          components: rust-src

      - name: Cache Rust build
        uses: Swatinem/rust-cache@v2
        with:
          save-if: ${{ github.ref == 'refs/heads/main' }}
          key: sanitizers

      # Run the core lib tests instrumented with AddressSanitizer. LeakSanitizer
      # is part of ASan; `detect_leaks=1` makes a leaked allocation fail the run.
      # `-Z build-std` rebuilds std with the same instrumentation so allocations
      # inside std are tracked too (and so std doesn't taint the report).
      - name: Test under AddressSanitizer
        env:
          RUSTFLAGS: "-Zsanitizer=address"
          RUSTDOCFLAGS: "-Zsanitizer=address"
          ASAN_OPTIONS: "detect_leaks=1"
          # Instrumented crypto competes with intentional subsecond network
          # deadlines when tests run concurrently. Keep every test and its
          # production timeout, but run one instrumented test at a time.
          RUST_TEST_THREADS: "1"
        run: |
          cargo +nightly test \
            -p mesh-talk-core --lib \
            -Z build-std \
            --target x86_64-unknown-linux-gnu
"}

