test("heavy hosted Linux builds reclaim only unused image SDKs before cache expansion", () => {
  const sources = [
    ["ci.yml", read("ci.yml")],
    ["hidden-contacts-native.yml", read("hidden-contacts-native.yml")],
    ["mutants.yml", read("mutants.yml")],
    ["sanitizers.yml", read("sanitizers.yml").split("  shards:\n")[1].split("  asan:\n")[0]],
    ["release.yml", read("release.yml").split("  build-release:\n")[1].split("  verify-release:\n")[0]],
  ];
  for (const [file, source] of sources) {
    const preparation = step(source, "Prepare hosted Linux build storage");
    assert.ok(preparation, `${file}: missing disk preparation`);
    assert.match(preparation, /runner.os == 'Linux'/);
    assert.match(preparation, /sudo --preserve-env=GITHUB_ACTIONS,RUNNER_ENVIRONMENT,RUNNER_OS/);
    assert.match(preparation, /scripts\/ci\/runner-storage\.mjs --prepare/);
    const index = source.indexOf("name: Prepare hosted Linux build storage");
    const cache = source.search(/uses: (?:Swatinem\/rust-cache|actions\/cache)@/);
    assert.ok(index >= 0 && cache > index, `${file}: restore must follow measured image reclamation`);
    assert.doesNotMatch(preparation, /cargo clean|rm -rf|hostedtoolcache|target\//);
    assert.match(preparation, /id: runner_storage/);
    assert.match(preparation, /tee "\$RUNNER_TEMP\/runner-storage\.json"/);
    const measurements = step(source, "Preserve runner storage measurements");
    assert.ok(measurements, `${file}: measurements must survive a later full-disk failure`);
    assert.match(measurements, /steps.runner_storage.outcome == 'success'/);
    assert.match(measurements, /name: runner-storage-/);
    assert.ok(source.indexOf("name: Preserve runner storage measurements") < cache);


async function main([mode, first, second, ...extra]) {
  assert.equal(extra.length, 0, "Unexpected ASan arguments");
  if (mode === "cohort" && !first) return cohort();
  const identity = await expectedIdentity();
  if (mode === "build" && first && !second) {
    assert.equal(identity.archive, null, "Producer cannot inherit another ASan archive");
    assert.ok(process.env.GITHUB_OUTPUT, "ASan producer requires GITHUB_OUTPUT");
    await verifyTools(identity, "nightly");
    const archive = await produceArchive(path.resolve(first), { buildArgs: ["--locked", "-p", "mesh-talk-core", "--lib", "-Z", "build-std", "--target", target], identity, cargoPrefix: ["+nightly"], afterBuild: async () => { await verifyTools(identity, "nightly"); assert.deepEqual(await expectedIdentity(), identity, "ASan source changed during compilation"); } });
    appendFileSync(process.env.GITHUB_OUTPUT, `archive_sha256=${archive.sha256}\nmanifest_sha256=${archive.manifestSha256}\n`);
    return archive;
  }
  if (mode === "smoke" && first && !second) return smoke(path.resolve(first), identity);
  if (mode === "shard" && first && second) {
    await verifyTools(identity);
    verifySmoke(second, identity);
    const directory = path.resolve("tmp/asan-build");
    const env = { ...process.env, CARGO_NET_OFFLINE: "true" };
    const cargoPrefix = [`+${identity.toolchain}`];
    const reuse = await reuseArchive(directory, path.resolve(second, "archive-runtime"), identity, { cargoPrefix, env });
    const result = await runPartition(Number(first), second, { ...reuse, identity, cargoPrefix, env, afterExecution: async () => { assert.deepEqual(await expectedIdentity(), identity, "ASan identity changed during execution"); await verifyArchive(directory, identity); } });
    assert.deepEqual(await expectedIdentity(), identity, "ASan identity changed during execution");
    return result;
  }
  if (mode === "verify" && first && !second) {
    assert.equal(process.env.MESH_ASAN_BUILD_RESULT, "success", "ASan archive producer must succeed");
    assert.ok(identity.archive, "ASan collector requires trusted archive digests");
    assert.equal(process.env.MESH_ASAN_SHARDS_RESULT, "success", "Every actual ASan shard must succeed");
    const root = path.resolve(first);
    const summary = collectAsan(root, identity);
    console.log(`ASan full union verified: ${summary.executedTests} passed, ${summary.ignoredTests} default ignored, ${summary.shards} exact-source partitions.`);
    return summary;
  }
  throw Error("Usage: asan.mjs cohort | build OUTPUT | smoke OUTPUT | shard INDEX OUTPUT | verify ARTIFACT_ROOT");
}
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main(process.argv.slice(2)).catch(error => { console.error(error.stack); process.exitCode = 1; });

